{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Cohort-based wellbeing guidance blending habits, frameworks, and friendly accountability.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="index.html">Home</a>
        <a href="about.html">Our Story</a>
        <a href="programs.html">Cohorts</a>
        <a href="services.html">Offerings</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Praise</a>
        <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="contact.html" class="muted">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>{{TAGLINE}}</h1>
          <p class="lede">Join a short, guided cohort that teaches simple practices, fresh perspectives, and tiny rituals you can actually keep. No medical advice — just useful frameworks and steady habits.</p>
          <p class="meta">Next cohort: small-group guidance, weekly labs, and peer accountability.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="programs.html">See Cohorts</a>
          </div>
        </div>
        <div class="hero-art">
          <svg class="pattern" viewBox="0 0 200 200" aria-hidden="true">
            <defs>
              <pattern id="p" width="20" height="20" patternUnits="userSpaceOnUse">
                <rect width="20" height="20" fill="#fff" />
                <circle cx="10" cy="10" r="3" fill="#F6E8FF" />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p)" />
          </svg>
          <div class="card highlight">
            <h3>Next cohort starts soon</h3>
            <p>Six weeks of practical micro-habits, weekly group labs, and an easy reflection rhythm to stick with.</p>
            <a class="btn" href="programs.html">Join a cohort</a>
          </div>
        </div>
      </div>
    </section>

    <!-- PROOF GALLERY (rotating testimonials) -->
    <section class="proof" id="proof">
      <div class="wrap">
        <h2>What people notice first</h2>
        <p class="sub">Small shifts people keep mentioning after a cohort.</p>
        <div class="proof-grid">
          <div class="testimony" aria-live="polite">
            <blockquote id="testimonial-text">Loading…</blockquote>
            <div class="byline" id="testimonial-author"></div>
            <div class="badges" id="testimonial-badges" aria-hidden="false"></div>
          </div>
          <div class="cred">
            <h3>Credibility</h3>
            <div class="cred-list">
              <div class="cred-item" data-tip="Practitioner-recommended cohort approach">Trusted peer facilitators</div>
              <div class="cred-item" data-tip="Practical frameworks used across cohorts">Framework-driven learning</div>
              <div class="cred-item" data-tip="Real people, small groups">Limited seats for better focus</div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT -->
    <section class="expect" id="expect">
      <div class="wrap">
        <h2>What to expect in a cohort</h2>
        <div class="cols">
          <div class="col">
            <h4>Weekly Labs</h4>
            <p>Short sessions that focus on a manageable practice and include time to try it in a small group.</p>
          </div>
          <div class="col">
            <h4>Practical Frameworks</h4>
            <p>Evidence-informed lifestyle frameworks translated into simple steps for daily life — no jargon.</p>
          </div>
          <div class="col">
            <h4>Habit Habitualizing</h4>
            <p>Tools to measure and shape a tiny, repeatable practice that helps you reach the outcome you want.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- OBJECTIONS -->
    <section class="objections" id="objections">
      <div class="wrap">
        <h2>Common questions</h2>
        <div class="qa">
          <div>
            <h5>Will this fit a busy schedule?</h5>
            <p>Yes — cohorts are designed with brief weekly sessions and tiny daily practices that stack into habit without extra stress.</p>
          </div>
          <div>
            <h5>Is this medical advice?</h5>
            <p>No. This is coaching that focuses on daily frameworks and habits, not diagnosis or treatment.</p>
          </div>
          <div>
            <h5>What if I miss a week?</h5>
            <p>Sessions are recorded and small groups keep the pace so you can rejoin without falling behind.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta" id="final-cta">
      <div class="wrap">
        <div class="cta-card">
          <h2>Ready to try a focused cohort?</h2>
          <p>Reserve a spot in the upcoming group or book a quick discovery chat.</p>
          <div class="cta-actions">
            <a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn large ghost" href="book.html">Schedule a discovery call</a>
          </div>
          <p class="contact">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <div class="muted">Cohort-style wellness coaching in {{CITY}}, {{STATE}}</div>
        </div>
        <div>
          <nav>
            <a href="about.html">Our Story</a>
            <a href="programs.html">Cohorts</a>
            <a href="pricing.html">Investment</a>
            <a href="contact.html">Contact</a>
          </nav>
        </div>
        <div class="copyright">&copy; <span id="year"></span> {{BUSINESS_NAME}}</div>
      </div>
    </div>
  </footer>

  <script>document.getElementById('year').textContent=new Date().getFullYear();</script>
</body>
</html>"} 
