{"path":"assets/css/styles.css","content":"/* Basic reset and variables */
:root{
  --bg:#fff9fe;
  --accent:#6b2fa5;
  --accent-2:#ff8fb2;
  --muted:#6b6b72;
  --card:#ffffff;
  --glass:rgba(255,255,255,0.7);
  --radius:12px;
  --shadow:0 8px 24px rgba(106,76,108,0.08);
  --mono:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:var(--mono);background:linear-gradient(180deg,var(--bg),#fff);color:#222}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg,rgba(107,47,165,0.06),rgba(255,143,178,0.03));backdrop-filter:blur(2px);}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.1rem}
.main-nav a{margin-left:18px;color:#444;text-decoration:none}
.main-nav a.cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.main-nav a.muted{color:var(--muted)}
.hero{padding:56px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
.hero-copy h1{font-size:clamp(1.6rem,3vw,2.4rem);margin:0 0 12px}
.lede{color:var(--muted);margin:0 0 8px}
.meta{color:var(--accent);font-weight:600}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid rgba(16,16,16,0.04);background:#fff;color:#222;box-shadow:var(--shadow)}
.btn.primary{background:var(--accent);color:#fff;border:none}
.btn.ghost{background:transparent;border:1px solid rgba(16,16,16,0.06)}
.btn.large{padding:14px 20px;border-radius:14px}
.hero-art{position:relative}
.pattern{width:100%;height:180px;border-radius:var(--radius);display:block}
.card.highlight{position:absolute;right:12px;bottom:-20px;background:linear-gradient(180deg,#fff,#fff);padding:18px;border-radius:12px;box-shadow:var(--shadow);width:260px}
.proof{padding:36px 0;background:linear-gradient(180deg,rgba(107,47,165,0.03),transparent)}
.proof h2{margin-top:0}
.proof-grid{display:grid;grid-template-columns:1fr 280px;gap:20px;align-items:start}
.testimony{background:var(--card);padding:22px;border-radius:12px;box-shadow:var(--shadow)}
.testimony blockquote{margin:0;font-style:italic;color:#333}
.byline{margin-top:12px;font-weight:600}
.badges{margin-top:12px;display:flex;gap:8px;flex-wrap:wrap}
.badge{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;padding:6px 8px;border-radius:8px;font-size:0.8rem;cursor:help}
.cred{padding:14px}
.cred-list{display:flex;flex-direction:column;gap:10px}
.cred-item{background:var(--glass);padding:10px;border-radius:10px;color:var(--muted)}
.expect{padding:36px 0}
.cols{display:flex;gap:20px}
.col{background:var(--card);padding:18px;border-radius:10px;flex:1;box-shadow:var(--shadow)}
.objections{padding:24px 0}
.qa{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.qa h5{margin:0 0 8px}
.final-cta{padding:40px 0}
.cta-card{background:linear-gradient(180deg,rgba(255,255,255,0.95),#fff);padding:22px;border-radius:14px;box-shadow:var(--shadow);display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.cta-actions{display:flex;gap:12px}
.site-footer{border-top:1px solid rgba(16,16,16,0.04);padding:20px 0;background:#fff}
.foot-grid{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted)}
/* Small screens */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .proof-grid{grid-template-columns:1fr}
  .cols{flex-direction:column}
  .qa{grid-template-columns:1fr}
  .main-nav{display:none}
}
/* Tooltip for badges (simple) */
.tooltip{position:absolute;background:#222;color:#fff;padding:8px 10px;border-radius:8px;font-size:0.85rem;white-space:nowrap;transform:translateY(-8px);opacity:0;pointer-events:none;transition:opacity .18s,transform .18s}
.tooltip.show{opacity:1;transform:translateY(0)}
/* Small util */
.hidden{display:none}
"} 
{"path":"assets/js/main.js","content":"// Main interactive behaviors: rotating proof gallery + pricing comparator
document.addEventListener('DOMContentLoaded',function(){
  // Testimonials dataset (kept local)
  const testimonials = [
    {text:'I keep a 3-minute morning practice now. It made decisions easier across the day.',author:'— S. (cohort participant)',badges:['micro-practices','peer-led']},
    {text:'The weekly lab helped me test tiny steps that actually stuck. No overwhelm.',author:'— J. (small business owner)',badges:['frameworks','practical']},
    {text':'Loved the group accountability. We shared wins and small experiments every week.',author:'— R. (teacher)',badges:['community','short-sessions']}
  ];

  let idx = 0;
  const txt = document.getElementById('testimonial-text');
  const auth = document.getElementById('testimonial-author');
  const badgesEl = document.getElementById('testimonial-badges');

  function showTestimonial(i){
    const t = testimonials[i];
    // fade animation
    txt.style.opacity = 0; auth.style.opacity = 0; badgesEl.style.opacity = 0;
    setTimeout(()=>{
      txt.textContent = t.text;
      auth.textContent = t.author;
      badgesEl.innerHTML = '';
      t.badges.forEach(b=>{
        const bEl = document.createElement('div');
        bEl.className='badge';
        bEl.tabIndex=0;
        bEl.textContent = b.replace(/-/g,' ');
        bEl.setAttribute('data-tip','Verified in cohort sessions');
        // custom tooltip interactions
        bEl.addEventListener('mouseenter', showTip);
        bEl.addEventListener('focus', showTip);
        bEl.addEventListener('mouseleave', hideTip);
        bEl.addEventListener('blur', hideTip);
        badgesEl.appendChild(bEl);
      });
      // fade in
      txt.style.opacity = 1; auth.style.opacity = 1; badgesEl.style.opacity = 1;
    },250);
  }

  function cycle(){
    idx = (idx+1) % testimonials.length;
    showTestimonial(idx);
  }

  showTestimonial(idx);
  const rot = setInterval(cycle,5500);

  // Tooltip element
  let tipEl;
  function ensureTip(){
    if(!tipEl){
      tipEl = document.createElement('div');
      tipEl.className='tooltip';
      document.body.appendChild(tipEl);
    }
  }
  function showTip(e){
    ensureTip();
    const content = e.currentTarget.getAttribute('data-tip') || '';
    tipEl.textContent = content;
    const rect = e.currentTarget.getBoundingClientRect();
    tipEl.style.left = (rect.left + window.scrollX + rect.width/2) + 'px';
    tipEl.style.top = (rect.top + window.scrollY - 10) + 'px';
    tipEl.classList.add('show');
    // basic positioning
    tipEl.style.transform = 'translate(-50%,-8px)';
  }
  function hideTip(){
    if(tipEl) tipEl.classList.remove('show');
  }

  // PRICING COMPARATOR (micro widget)
  // We'll dynamically inject a small comparator into the hero card for quick preview
  const heroCard = document.querySelector('.card.highlight');
  if(heroCard){
    const comp = document.createElement('div');
    comp.className='pricing-compare';
    comp.innerHTML = '\n      <div style="display:flex;gap:8px;align-items:center;margin-bottom:8px">\n        <button class="btn small active" data-plan="month">Monthly</button>\n        <button class="btn small" data-plan="package">Package</button>\n      </div>\n      <div style="display:flex;align-items:baseline;gap:10px">\n        <div style="font-size:1.4rem;font-weight:700">$<span id="price-num">99</span></div>\n        <div class="muted" id="price-term">/month</div>\n      </div>\n    ';
    comp.style.marginTop='12px';
    heroCard.appendChild(comp);

    const priceNum = comp.querySelector('#price-num');
    const priceTerm = comp.querySelector('#price-term');
    const btns = comp.querySelectorAll('button[data-plan]');
    // Pricing values (unique names & framing)
    const pricing = {month:99,package:399};
    let current = pricing.month;

    function animateNumber(el,from,to,duration){
      const start = performance.now();
      function frame(now){
        const t = Math.min(1,(now-start)/duration);
        const value = Math.round(from + (to-from)*t);
        el.textContent = value;
        if(t < 1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    btns.forEach(b=>{
      b.addEventListener('click',()=>{
        btns.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        const plan = b.getAttribute('data-plan');
        const target = pricing[plan];
        animateNumber(priceNum,parseInt(priceNum.textContent,10), target, 500);
        priceTerm.textContent = plan==='month'?'/month':'one-time package';
      });
    });
    // style small buttons
    comp.querySelectorAll('.btn.small').forEach(b=>{b.style.padding='6px 8px';b.style.borderRadius='8px';b.style.fontSize='0.85rem'});
  }

});
"} 
